+/* Hero Section */
+.hero {
+    background: linear-gradient(rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.7)), url('https://via.placeholder.com/1920x800/121212/333?text=Hero+Image') no-repeat center center / cover;
+    padding: 100px 16px;
