+            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
+            
+            // Toggle ARIA expanded state
+            menuToggle.setAttribute('aria-expanded', !isExpanded);
+            
+            // Toggle visual class
+            mainNav.classList.toggle('is-open');
+        });
+        
+        // Allow closing menu with Escape key when open
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'Escape' && mainNav.classList.contains('is-open')) {
+                menuToggle.setAttribute('aria-expanded', 'false');
+                mainNav.classList.remove('is-open');
+                menuToggle.focus();
+            }
+        });
+    }
+
+    // 2. Add to cart functionality simulation
+    const addToCartBtns = document.querySelectorAll('.add-to-cart');
+    const cartCountEl = document.querySelector('.cart-count');
+    const cartBtn = document.querySelector('.cart-btn');
+    const liveRegion = document.getElementById('live-region');
+    
+    let cartItemCount = 0;
+
+    addToCartBtns.forEach(btn => {
+        btn.addEventListener('click', (e) => {
+            // Increment cart
+            cartItemCount++;
+            cartCountEl.textContent = cartItemCount;
+            
+            // Extract product name for accurate screen reader announcements
+            const srText = btn.querySelector('.sr-only');
+            const productName = srText ? srText.textContent.replace(', ', '') : 'Product';
+            
+            // Update live region so screen readers announce the cart addition
+            liveRegion.textContent = `${productName} added to cart. You now have ${cartItemCount} item${cartItemCount !== 1 ? 's' : ''} in your cart.`;
+            
+            // Update the accessible name of the cart button itself
+            cartBtn.setAttribute('aria-label', `Cart (${cartItemCount} items)`);
+
+            // Temporary visual feedback
+            const originalHTML = btn.innerHTML;
+            btn.innerHTML = `Added! <span class="sr-only">, ${productName}</span>`;
+            btn.style.backgroundColor = '#4caf50'; // Success green
+            btn.style.borderColor = '#4caf50';
+            btn.style.color = '#fff';
+            
+            // Reset button visual state after 2 seconds
+            setTimeout(() => {
+                btn.innerHTML = originalHTML;
+                btn.style.backgroundColor = '';
+                btn.style.borderColor = '';
+                btn.style.color = '';
+            }, 2000);
+        });
+    });
+});
